#define FHCRC           (1 << 1)
#define FEXTRA          (1 << 2)
#define FNAME           (1 << 3)
#define FCOMMENT        (1 << 4)


private int
uncompressgzipped(const unsigned char *old, unsigned char **newch,
    size_t bytes_max, size_t *n)
{
        unsigned char flg = old[3];
        size_t data_start = 10;

        if (flg & FEXTRA) {
                if (data_start + 1 >= *n)
                        goto err;
                data_start += 2 + old[data_start] + old[data_start + 1] * 256;
        }
        if (flg & FNAME) {
                while(data_start < *n && old[data_start])
                        data_start++;
                data_start++;
        }
        if (flg & FCOMMENT) {
                while(data_start < *n && old[data_start])
                        data_start++;
                data_start++;
        }
        if (flg & FHCRC)
                data_start += 2;

        if (data_start >= *n)
                goto err;

        *n -= data_start;
        old += data_start;
        return uncompresszlib(old, newch, bytes_max, n, 0);
err:
        return makeerror(newch, n, "File too short");
}

private int
uncompresszlib(const unsigned char *old, unsigned char **newch,
    size_t bytes_max, size_t *n, int zlib)
{
        int rc;
        z_stream z;

        if ((*newch = CAST(unsigned char *, malloc(bytes_max + 1))) == NULL)
                return makeerror(newch, n, "No buffer, %s", strerror(errno));

        z.next_in = CCAST(Bytef *, old);
        z.avail_in = CAST(uint32_t, *n);
        z.next_out = *newch;
        z.avail_out = CAST(unsigned int, bytes_max);
        z.zalloc = Z_NULL;
        z.zfree = Z_NULL;
        z.opaque = Z_NULL;

        /* LINTED bug in header macro */
        rc = zlib ? inflateInit(&z) : inflateInit2(&z, -15);
        if (rc != Z_OK)
                goto err;

        rc = inflate(&z, Z_SYNC_FLUSH);
        if (rc != Z_OK && rc != Z_STREAM_END)
                goto err;

        *n = CAST(size_t, z.total_out);
        rc = inflateEnd(&z);
        if (rc != Z_OK)
                goto err;

        /* let's keep the nul-terminate tradition */
        (*newch)[*n] = '\0';

        return OKDATA;
err:
        free(*newch);
        return makeerror(newch, n, "%s", z.msg ? z.msg : zError(rc));
}
#endif

